export function requeueJob(db: DatabaseSync, id: string, runAfter: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?`,
  ).run(runAfter, nowIso(), id);
}

/** On worker start: any job left `running` by a dead worker is queued again. Its interrupted attempt stays counted in `attempts`. */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  return Number(
    db
      .prepare(
        `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ?
         WHERE status = 'running'`,
      )
      .run(nowIso()).changes,
  );
}

